// Shared console UI translations. Order: es pt fr de ru tr pl it zh ja ko th vi id hi sr nl ka ar he.
// Product names, filenames, paths and compatibility values remain unchanged.
const LANGS = ['es','pt','fr','de','ru','tr','pl','it','zh','ja','ko','th','vi','id','hi','sr','nl','ka','ar','he'];
const table = {};
function row(key, values) {
  const cells = values.split('|');
  if (cells.length !== LANGS.length || cells.some(value => !value.trim())) throw Error('Invalid translation row: ' + key + ' (' + cells.length + ')');
  const sourceTokens = (key.match(/\{\w+\}/g) || []).sort().join(',');
  table[key] = Object.fromEntries(LANGS.map((code, index) => {
    if ((cells[index].match(/\{\w+\}/g) || []).sort().join(',') !== sourceTokens) throw Error('Placeholder mismatch: ' + code + ' ' + key);
    return [code, cells[index]];
  }));
}
function alias(key, source) { table[key] = {...table[source]}; }
