// Native options are one text node. Distinct captures keep independently pinned
// game/menu versions, formats and title IDs literal; missing values use exact
// more-specific templates so the translated fallback never changes a product.
for (const withTitleIds of [false, true]) for (const gameMissing of [false, true]) for (const menuMissing of [false, true]) {
  const key = 'Game update: ' + (gameMissing ? 'Not provided' : '{gameVersion}') +
    ' · Menu version: ' + (menuMissing ? 'Not provided' : '{menuVersion}') +
    ' · {format}' + (withTitleIds ? ' · {titleIds}' : '');
  row(key, LANGS.map(code => table['Game update'][code] + ': ' +
    (gameMissing ? table['Not provided'][code] : '{gameVersion}') +
    ' · ' + table['Menu version'][code] + ': ' +
    (menuMissing ? table['Not provided'][code] : '{menuVersion}') +
    ' · {format}' + (withTitleIds ? ' · {titleIds}' : '')).join('|'));
}
for (const caption of ['Menu cover', 'Game artwork', 'Menu preview', 'Project preview']) {
  row('{name} · ' + caption, LANGS.map(code => '{name} · ' + table[caption][code]).join('|'));
}

